// All overworld art is generated procedurally at boot — tiles, character
// sprites, and a 5x7 bitmap font. Pokémon battle sprites are PNGs on disk.
window.Gfx = (() => {
  const TILE = 16;

  function makeCanvas(w, h) {
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    return c;
  }

  // Deterministic pseudo-random for speckle textures.
  function rng(seed) {
    let s = seed;
    return () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
  }

  function px(ctx, x, y, c) { ctx.fillStyle = c; ctx.fillRect(x, y, 1, 1); }

  // ---- Tile painters -------------------------------------------------------
  const T = {}; // name -> canvas

  function tile(name, fn) {
    const c = makeCanvas(TILE, TILE);
    fn(c.getContext('2d'));
    T[name] = c;
  }

  function speckle(ctx, base, dots, n, seed) {
    ctx.fillStyle = base; ctx.fillRect(0, 0, TILE, TILE);
    const r = rng(seed);
    for (let i = 0; i < n; i++) px(ctx, (r() * 16) | 0, (r() * 16) | 0, dots[(r() * dots.length) | 0]);
  }

  tile('grass', c => speckle(c, '#70c060', ['#5cae4c', '#80d070', '#64b854'], 26, 7));
  tile('grass2', c => speckle(c, '#70c060', ['#5cae4c', '#80d070'], 26, 99));
  tile('tallgrass', c => {
    speckle(c, '#58a848', ['#4c9c3c'], 10, 13);
    c.fillStyle = '#2e7c28';
    for (let i = 0; i < 4; i++) {
      const x = 1 + i * 4;
      c.fillRect(x, 4, 2, 11); c.fillRect(x - 1, 6, 1, 4); c.fillRect(x + 2, 7, 1, 4);
    }
    c.fillStyle = '#3f9434';
    for (let i = 0; i < 4; i++) c.fillRect(2 + i * 4, 5, 1, 9);
  });
  tile('path', c => speckle(c, '#e8d8a0', ['#d8c890', '#f0e0b0', '#d0bc84'], 22, 21));
  tile('sand', c => speckle(c, '#f0e0b0', ['#e4d09c', '#f8ecc4'], 20, 31));
  tile('water', c => {
    c.fillStyle = '#5090e8'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#70a8f0';
    c.fillRect(1, 3, 5, 1); c.fillRect(9, 7, 5, 1); c.fillRect(3, 12, 5, 1);
  });
  tile('water2', c => {
    c.fillStyle = '#5090e8'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#70a8f0';
    c.fillRect(3, 4, 5, 1); c.fillRect(7, 9, 5, 1); c.fillRect(1, 13, 5, 1);
  });
  tile('tree', c => {
    speckle(c, '#70c060', ['#5cae4c'], 10, 47);
    c.fillStyle = '#7a4a2a'; c.fillRect(6, 11, 4, 5);
    c.fillStyle = '#2a7c34';
    c.beginPath(); c.fillRect(2, 4, 12, 8); c.fillRect(4, 1, 8, 4);
    c.fillStyle = '#3c9c44';
    c.fillRect(4, 2, 6, 2); c.fillRect(3, 5, 7, 3); c.fillRect(5, 9, 4, 2);
    c.fillStyle = '#1e5c26'; c.fillRect(2, 10, 12, 2);
  });
  tile('fence', c => {
    speckle(c, '#70c060', ['#5cae4c'], 10, 53);
    c.fillStyle = '#c8a050';
    c.fillRect(2, 5, 3, 9); c.fillRect(11, 5, 3, 9); c.fillRect(0, 7, 16, 3);
    c.fillStyle = '#8a6830';
    c.fillRect(2, 13, 3, 1); c.fillRect(11, 13, 3, 1); c.fillRect(0, 9, 16, 1);
  });
  tile('flower', c => {
    speckle(c, '#70c060', ['#5cae4c'], 14, 61);
    const f = (x, y, col) => {
      px(c, x, y - 1, col); px(c, x - 1, y, col); px(c, x + 1, y, col); px(c, x, y + 1, col);
      px(c, x, y, '#f8d020');
    };
    f(4, 5, '#f06060'); f(11, 10, '#f0f0f0');
  });
  tile('sign', c => {
    speckle(c, '#70c060', ['#5cae4c'], 10, 71);
    c.fillStyle = '#8a6830'; c.fillRect(7, 9, 2, 6);
    c.fillStyle = '#c8a050'; c.fillRect(2, 3, 12, 7);
    c.fillStyle = '#8a6830'; c.fillRect(2, 9, 12, 1);
    c.fillStyle = '#6a4a20'; c.fillRect(4, 5, 8, 1); c.fillRect(4, 7, 6, 1);
  });
  tile('ledge', c => {
    speckle(c, '#70c060', ['#5cae4c'], 12, 77);
    c.fillStyle = '#b89858'; c.fillRect(0, 10, 16, 4);
    c.fillStyle = '#8a7038'; c.fillRect(0, 14, 16, 2);
    c.fillStyle = '#d8c890'; c.fillRect(0, 10, 16, 1);
  });
  // Buildings (exterior)
  const ROOF = { R: '#e86840', B: '#5878e8', P: '#9858c8', G: '#58a868', Y: '#d8a838' };
  for (const [k, col] of Object.entries(ROOF)) {
    tile('roof' + k, c => {
      c.fillStyle = col; c.fillRect(0, 0, 16, 16);
      c.fillStyle = 'rgba(0,0,0,.25)';
      c.fillRect(0, 5, 16, 1); c.fillRect(0, 11, 16, 1);
      c.fillStyle = 'rgba(255,255,255,.25)'; c.fillRect(0, 0, 16, 2);
    });
  }
  tile('wall', c => {
    c.fillStyle = '#e8e0d0'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#c8c0b0';
    c.fillRect(0, 7, 16, 1); c.fillRect(0, 15, 16, 1);
    c.fillRect(7, 0, 1, 7); c.fillRect(3, 8, 1, 7); c.fillRect(11, 8, 1, 7);
  });
  tile('window', c => {
    c.fillStyle = '#e8e0d0'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#404858'; c.fillRect(2, 3, 12, 10);
    c.fillStyle = '#88a8d8'; c.fillRect(3, 4, 10, 8);
    c.fillStyle = '#c8e0f8'; c.fillRect(4, 5, 3, 3);
  });
  tile('door', c => {
    c.fillStyle = '#e8e0d0'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#7a4a2a'; c.fillRect(2, 1, 12, 15);
    c.fillStyle = '#9a6a3a'; c.fillRect(3, 2, 10, 13);
    c.fillStyle = '#5a3a1a'; c.fillRect(3, 8, 10, 1);
    px(c, 11, 10, '#f8d020');
  });
  tile('cavewall', c => {
    speckle(c, '#7a6a58', ['#6a5a48', '#8a7a68'], 18, 83);
    c.fillStyle = '#4a3e30'; c.fillRect(0, 14, 16, 2); c.fillRect(0, 0, 16, 1);
    c.fillStyle = '#9a8a78'; c.fillRect(2, 2, 5, 3); c.fillRect(9, 7, 5, 3);
  });
  tile('cavefloor', c => speckle(c, '#b8a890', ['#a89880', '#c8b8a0'], 24, 89));
  // Interiors
  tile('floor', c => {
    c.fillStyle = '#e0c890'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#d0b880'; c.fillRect(0, 0, 16, 1); c.fillRect(0, 0, 1, 16);
    c.fillRect(8, 0, 1, 16); c.fillRect(0, 8, 16, 1);
  });
  tile('wallint', c => {
    c.fillStyle = '#c8b8d8'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#a898b8'; c.fillRect(0, 12, 16, 4);
    c.fillStyle = '#e0d0f0'; c.fillRect(0, 0, 16, 2);
  });
  tile('counter', c => {
    c.fillStyle = '#d87858'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#f0a888'; c.fillRect(0, 0, 16, 4);
    c.fillStyle = '#a85838'; c.fillRect(0, 13, 16, 3);
  });
  tile('shelf', c => {
    c.fillStyle = '#9a6a3a'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#6a4a20'; c.fillRect(0, 6, 16, 2); c.fillRect(0, 14, 16, 2);
    c.fillStyle = '#e85858'; c.fillRect(2, 2, 3, 4);
    c.fillStyle = '#5878e8'; c.fillRect(6, 2, 3, 4); c.fillRect(2, 9, 3, 5);
    c.fillStyle = '#58a868'; c.fillRect(11, 2, 3, 4); c.fillRect(7, 9, 3, 5);
  });
  tile('mat', c => {
    c.fillStyle = '#58b868'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#388848'; c.fillRect(1, 1, 14, 14);
    c.fillStyle = '#58b868'; c.fillRect(3, 3, 10, 10);
  });
  tile('pc', c => {
    c.fillStyle = '#c8b8d8'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#888898'; c.fillRect(2, 2, 12, 11);
    c.fillStyle = '#202830'; c.fillRect(3, 3, 10, 7);
    c.fillStyle = '#40e890'; c.fillRect(4, 4, 8, 2); c.fillRect(4, 7, 5, 1);
    c.fillStyle = '#666676'; c.fillRect(4, 13, 8, 2);
  });
  tile('healer', c => {
    c.fillStyle = '#d87858'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#e8e8f0'; c.fillRect(1, 1, 14, 12);
    c.fillStyle = '#c83838';
    c.fillRect(3, 3, 4, 3); c.fillRect(9, 3, 4, 3); c.fillRect(3, 8, 4, 3); c.fillRect(9, 8, 4, 3);
    c.fillStyle = '#f0f0f8'; px(c, 4, 4); c.fillStyle = '#ffb0b0';
  });
  tile('table', c => {
    c.fillStyle = '#e0c890'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#b08848'; c.fillRect(1, 2, 14, 12);
    c.fillStyle = '#d0a868'; c.fillRect(2, 3, 12, 9);
  });
  tile('void', c => { c.fillStyle = '#101018'; c.fillRect(0, 0, 16, 16); });

  // ---- Character sprites ---------------------------------------------------
  // 16x16 string art. Palette keys: H hair, S skin, T shirt, P pants, W white, K black(outline)
  const HERO_DOWN_STAND = [
    '................',
    '.....HHHHHH.....',
    '....HHHHHHHH....',
    '...HHHHHHHHHH...',
    '...HHSSSSSSHH...',
    '...HSSKSSKSSH...',
    '....SSSSSSSS....',
    '.....SSSSSS.....',
    '....TTTTTTTT....',
    '...TTTTTTTTTT...',
    '...STTTTTTTTS...',
    '....TTTTTTTT....',
    '.....PPPPPP.....',
    '.....PP..PP.....',
    '.....KK..KK.....',
    '................',
  ];
  const HERO_DOWN_WALK = [
    '................',
    '.....HHHHHH.....',
    '....HHHHHHHH....',
    '...HHHHHHHHHH...',
    '...HHSSSSSSHH...',
    '...HSSKSSKSSH...',
    '....SSSSSSSS....',
    '.....SSSSSS.....',
    '....TTTTTTTT....',
    '...TTTTTTTTTT...',
    '...STTTTTTTTS...',
    '....TTTTTTTT....',
    '.....PPPPPP.....',
    '....PP....PP....',
    '....KK....KK....',
    '................',
  ];
  const HERO_UP_STAND = HERO_DOWN_STAND.map(r => r.replace(/K/g, 'H')).map((r, i) =>
    i === 5 ? r.replace(/S/g, 'H') : i === 4 ? r.replace(/S/g, 'H') : r);
  const HERO_UP_WALK = HERO_DOWN_WALK.map(r => r.replace(/K/g, 'H')).map((r, i) =>
    i === 5 ? r.replace(/S/g, 'H') : i === 4 ? r.replace(/S/g, 'H') : r);
  const HERO_LEFT_STAND = [
    '................',
    '.....HHHHHH.....',
    '....HHHHHHHH....',
    '...HHHHHHHHHH...',
    '...HSSSSSSHH....',
    '...HSKSSSHHH....',
    '...SSSSSSHH.....',
    '....SSSSSS......',
    '....TTTTTTTT....',
    '...TTTTTTTTT....',
    '...STTTTTTTT....',
    '....TTTTTTTT....',
    '.....PPPPPP.....',
    '.....PPPPP......',
    '.....KK.KK......',
    '................',
  ];
  const HERO_LEFT_WALK = [
    '................',
    '................',
    '.....HHHHHH.....',
    '....HHHHHHHH....',
    '...HHHHHHHHHH...',
    '...HSSSSSSHH....',
    '...HSKSSSHHH....',
    '...SSSSSSHH.....',
    '....SSSSSS......',
    '....TTTTTTTT....',
    '...TTTTTTTTT....',
    '....TTTTTTTT....',
    '....PPPPPPP.....',
    '...PPP...PPP....',
    '...KK.....KK....',
    '................',
  ];

  function paintSprite(rows, pal, flip) {
    const c = makeCanvas(16, 16);
    const ctx = c.getContext('2d');
    for (let y = 0; y < 16; y++) {
      for (let x = 0; x < 16; x++) {
        const ch = rows[y][flip ? 15 - x : x];
        if (ch !== '.' && pal[ch]) px(ctx, x, y, pal[ch]);
      }
    }
    return c;
  }

  // Build a character sheet: {down:[stand,walkA,walkB], up:[...], left:[...], right:[...]}
  function makeCharSheet(pal) {
    const mk = (rows, flip) => paintSprite(rows, pal, flip);
    const downW = mk(HERO_DOWN_WALK), upW = mk(HERO_UP_WALK);
    return {
      down: [mk(HERO_DOWN_STAND), downW, downW],
      up: [mk(HERO_UP_STAND), upW, upW],
      left: [mk(HERO_LEFT_STAND), mk(HERO_LEFT_WALK)],
      right: [mk(HERO_LEFT_STAND, true), mk(HERO_LEFT_WALK, true)],
    };
  }

  const PALETTES = {
    hero:   { H: '#c83830', S: '#f8c898', T: '#3858c8', P: '#283048', W: '#f8f8f8', K: '#202020' },
    rival:  { H: '#8a5a30', S: '#f8c898', T: '#5848a8', P: '#383838', W: '#f8f8f8', K: '#202020' },
    oak:    { H: '#d8d8d8', S: '#f0c090', T: '#e8e8e8', P: '#705838', W: '#f8f8f8', K: '#202020' },
    mom:    { H: '#a85828', S: '#f8c898', T: '#e87898', P: '#c85878', W: '#f8f8f8', K: '#202020' },
