// All overworld art is generated procedurally at boot — tiles, character
// sprites, and a 5x7 bitmap font. Pokémon battle sprites are PNGs on disk.
window.Gfx = (() => {
  const TILE = 16;

  function makeCanvas(w, h) {
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    return c;
  }

  // Deterministic pseudo-random for speckle textures.
  function rng(seed) {
    let s = seed;
    return () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
  }

  function px(ctx, x, y, c) { ctx.fillStyle = c; ctx.fillRect(x, y, 1, 1); }

  // ---- Tile painters -------------------------------------------------------
  const T = {}; // name -> canvas

  function tile(name, fn) {
    const c = makeCanvas(TILE, TILE);
    fn(c.getContext('2d'));
    T[name] = c;
  }

  function speckle(ctx, base, dots, n, seed) {
    ctx.fillStyle = base; ctx.fillRect(0, 0, TILE, TILE);
    const r = rng(seed);
    for (let i = 0; i < n; i++) px(ctx, (r() * 16) | 0, (r() * 16) | 0, dots[(r() * dots.length) | 0]);
  }

  tile('grass', c => speckle(c, '#70c060', ['#5cae4c', '#80d070', '#64b854'], 26, 7));
  tile('grass2', c => speckle(c, '#70c060', ['#5cae4c', '#80d070'], 26, 99));
  tile('tallgrass', c => {
    speckle(c, '#58a848', ['#4c9c3c'], 10, 13);
    c.fillStyle = '#2e7c28';
    for (let i = 0; i < 4; i++) {
      const x = 1 + i * 4;
      c.fillRect(x, 4, 2, 11); c.fillRect(x - 1, 6, 1, 4); c.fillRect(x + 2, 7, 1, 4);
    }
    c.fillStyle = '#3f9434';
    for (let i = 0; i < 4; i++) c.fillRect(2 + i * 4, 5, 1, 9);
  });
  tile('path', c => speckle(c, '#e8d8a0', ['#d8c890', '#f0e0b0', '#d0bc84'], 22, 21));
  tile('sand', c => speckle(c, '#f0e0b0', ['#e4d09c', '#f8ecc4'], 20, 31));
  tile('water', c => {
    c.fillStyle = '#5090e8'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#70a8f0';
    c.fillRect(1, 3, 5, 1); c.fillRect(9, 7, 5, 1); c.fillRect(3, 12, 5, 1);
  });
  tile('water2', c => {
    c.fillStyle = '#5090e8'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#70a8f0';
    c.fillRect(3, 4, 5, 1); c.fillRect(7, 9, 5, 1); c.fillRect(1, 13, 5, 1);
  });
  tile('tree', c => {
    speckle(c, '#70c060', ['#5cae4c'], 10, 47);
    c.fillStyle = '#7a4a2a'; c.fillRect(6, 11, 4, 5);
    c.fillStyle = '#2a7c34';
    c.beginPath(); c.fillRect(2, 4, 12, 8); c.fillRect(4, 1, 8, 4);
    c.fillStyle = '#3c9c44';
    c.fillRect(4, 2, 6, 2); c.fillRect(3, 5, 7, 3); c.fillRect(5, 9, 4, 2);
    c.fillStyle = '#1e5c26'; c.fillRect(2, 10, 12, 2);
  });
  tile('fence', c => {
    speckle(c, '#70c060', ['#5cae4c'], 10, 53);
    c.fillStyle = '#c8a050';
    c.fillRect(2, 5, 3, 9); c.fillRect(11, 5, 3, 9); c.fillRect(0, 7, 16, 3);
    c.fillStyle = '#8a6830';
    c.fillRect(2, 13, 3, 1); c.fillRect(11, 13, 3, 1); c.fillRect(0, 9, 16, 1);
  });
  tile('flower', c => {
    speckle(c, '#70c060', ['#5cae4c'], 14, 61);
    const f = (x, y, col) => {
      px(c, x, y - 1, col); px(c, x - 1, y, col); px(c, x + 1, y, col); px(c, x, y + 1, col);
      px(c, x, y, '#f8d020');
    };
    f(4, 5, '#f06060'); f(11, 10, '#f0f0f0');
  });
  tile('sign', c => {
    speckle(c, '#70c060', ['#5cae4c'], 10, 71);
    c.fillStyle = '#8a6830'; c.fillRect(7, 9, 2, 6);
    c.fillStyle = '#c8a050'; c.fillRect(2, 3, 12, 7);
    c.fillStyle = '#8a6830'; c.fillRect(2, 9, 12, 1);
    c.fillStyle = '#6a4a20'; c.fillRect(4, 5, 8, 1); c.fillRect(4, 7, 6, 1);
  });
  tile('ledge', c => {
