      c.fillStyle = 'rgba(255,255,255,.25)'; c.fillRect(0, 0, 16, 2);
    });
  }
  tile('wall', c => {
    c.fillStyle = '#e8e0d0'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#c8c0b0';
    c.fillRect(0, 7, 16, 1); c.fillRect(0, 15, 16, 1);
    c.fillRect(7, 0, 1, 7); c.fillRect(3, 8, 1, 7); c.fillRect(11, 8, 1, 7);
  });
  tile('window', c => {
    c.fillStyle = '#e8e0d0'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#404858'; c.fillRect(2, 3, 12, 10);
    c.fillStyle = '#88a8d8'; c.fillRect(3, 4, 10, 8);
    c.fillStyle = '#c8e0f8'; c.fillRect(4, 5, 3, 3);
  });
  tile('door', c => {
    c.fillStyle = '#e8e0d0'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#7a4a2a'; c.fillRect(2, 1, 12, 15);
    c.fillStyle = '#9a6a3a'; c.fillRect(3, 2, 10, 13);
    c.fillStyle = '#5a3a1a'; c.fillRect(3, 8, 10, 1);
    px(c, 11, 10, '#f8d020');
  });
  tile('cavewall', c => {
    speckle(c, '#7a6a58', ['#6a5a48', '#8a7a68'], 18, 83);
    c.fillStyle = '#4a3e30'; c.fillRect(0, 14, 16, 2); c.fillRect(0, 0, 16, 1);
    c.fillStyle = '#9a8a78'; c.fillRect(2, 2, 5, 3); c.fillRect(9, 7, 5, 3);
  });
  tile('cavefloor', c => speckle(c, '#b8a890', ['#a89880', '#c8b8a0'], 24, 89));
  // Interiors
  tile('floor', c => {
    c.fillStyle = '#e0c890'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#d0b880'; c.fillRect(0, 0, 16, 1); c.fillRect(0, 0, 1, 16);
    c.fillRect(8, 0, 1, 16); c.fillRect(0, 8, 16, 1);
  });
  tile('wallint', c => {
    c.fillStyle = '#c8b8d8'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#a898b8'; c.fillRect(0, 12, 16, 4);
    c.fillStyle = '#e0d0f0'; c.fillRect(0, 0, 16, 2);
  });
  tile('counter', c => {
    c.fillStyle = '#d87858'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#f0a888'; c.fillRect(0, 0, 16, 4);
    c.fillStyle = '#a85838'; c.fillRect(0, 13, 16, 3);
