    c.fillStyle = '#e85858'; c.fillRect(2, 2, 3, 4);
    c.fillStyle = '#5878e8'; c.fillRect(6, 2, 3, 4); c.fillRect(2, 9, 3, 5);
    c.fillStyle = '#58a868'; c.fillRect(11, 2, 3, 4); c.fillRect(7, 9, 3, 5);
