  tile('mat', c => {
    c.fillStyle = '#58b868'; c.fillRect(0, 0, 16, 16);
    c.fillStyle = '#388848'; c.fillRect(1, 1, 14, 14);
    c.fillStyle = '#58b868'; c.fillRect(3, 3, 10, 10);
  });
  tile('pc', c => {
    c.fillStyle = '#c8b8d8'; c.fillRect(0, 0, 16, 16);
