// Headless data validation: pokedex integrity, move references, obtainability of all 151.
import { readFileSync } from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '..');
global.window = global;
const load = (p) => (0, eval)(readFileSync(path.join(ROOT, p), 'utf8'));
load('assets/data/pokedex.js');
load('assets/data/moves.js');
load('js/typechart.js');
load('js/pokemon.js');
load('js/maps.js');

let fails = 0;
const check = (cond, msg) => { if (!cond) { console.error('FAIL:', msg); fails++; } };

// 1. Pokedex integrity
check(Object.keys(POKEDEX).length === 151, 'pokedex has 151 entries');
for (let id = 1; id <= 151; id++) {
  const sp = POKEDEX[id];
  check(sp, `species ${id} exists`);
  for (const k of ['hp', 'atk', 'def', 'spa', 'spd', 'spe'])
    check(Number.isFinite(sp.stats[k]) && sp.stats[k] > 0, `species ${id} stat ${k}`);
  check(sp.types.length >= 1, `species ${id} types`);
  check(sp.types.every(t => TYPE_CHART[t]), `species ${id} known types: ${sp.types}`);
  check(['fast', 'slow', 'medium', 'medium-slow'].includes(sp.growth), `species ${id} growth ${sp.growth}`);
  check(sp.catchRate > 0, `species ${id} catchRate`);
  const usable = sp.learnset.filter(l => MOVES[l.move]);
  check(usable.length > 0 || id === 132, `species ${id} (${sp.name}) has learnable moves`);
  for (const l of sp.learnset) check(MOVES[l.move], `species ${id} move ${l.move} exists`);
  for (const e of sp.evolvesTo) {
    check(e.to >= 1 && e.to <= 151, `species ${id} evo target ${e.to}`);
    check(e.method === 'level' ? e.level > 0 : true, `species ${id} evo level`);
    if (e.method === 'stone') check(Pkmn.ITEMS[e.item], `species ${id} (${sp.name}) stone ${e.item} is purchasable`);
  }
}

// 2. Moves integrity
for (const [name, mv] of Object.entries(MOVES)) {
  check(mv.pp > 0, `move ${name} pp`);
  check(TYPE_CHART[mv.type], `move ${name} type ${mv.type}`);
  check(['physical', 'special', 'status'].includes(mv.damageClass), `move ${name} class`);
}

// 3. Encounter tables reference valid species
const wildIds = new Set();
for (const [area, table] of Object.entries(Maps.ENC)) {
  for (const [id, w, lo, hi] of table) {
    check(POKEDEX[id], `${area}: species ${id}`);
    check(w > 0 && lo >= 1 && hi >= lo && hi <= 100, `${area}: ${id} weight/levels`);
    wildIds.add(id);
  }
}

// 4. Obtainability closure: starters + wilds, expanded through evolutions
const obtainable = new Set([1, 4, 7, ...wildIds]);
let grew = true;
while (grew) {
  grew = false;
  for (const id of [...obtainable]) {
    for (const e of POKEDEX[id].evolvesTo) {
      if (!obtainable.has(e.to)) { obtainable.add(e.to); grew = true; }
    }
  }
}
const missing = [];
for (let id = 1; id <= 151; id++) if (!obtainable.has(id)) missing.push(id + ':' + POKEDEX[id].name);
check(missing.length === 0, 'unobtainable species: ' + missing.join(', '));

// 5. Stat math sanity at multiple levels
for (let id = 1; id <= 151; id++) {
  for (const lv of [5, 36, 100]) {
    const m = Pkmn.make(id, lv);
    check(m.hp > 0 && m.moves.length >= 1 && m.moves.length <= 4, `make(${id},${lv})`);
    check(m.moves.every(mv => MOVES[mv.name]), `make(${id},${lv}) moves valid`);
