const load = (p) => (0, eval)(readFileSync(path.join(ROOT, p), 'utf8'));
load('assets/data/pokedex.js');
load('assets/data/moves.js');
load('js/typechart.js');
load('js/pokemon.js');
load('js/maps.js');

let fails = 0;
const check = (cond, msg) => { if (!cond) { console.error('FAIL:', msg); fails++; } };

