  check(sp.types.length >= 1, `species ${id} types`);
  check(sp.types.every(t => TYPE_CHART[t]), `species ${id} known types: ${sp.types}`);
  check(['fast', 'slow', 'medium', 'medium-slow'].includes(sp.growth), `species ${id} growth ${sp.growth}`);
  check(sp.catchRate > 0, `species ${id} catchRate`);
  const usable = sp.learnset.filter(l => MOVES[l.move]);
