// FireRed is Gen 3: the Fairy type doesn't exist yet. Strip it from the data.
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
const ROOT = path.resolve(import.meta.dirname, '..');

const dexPath = path.join(ROOT, 'assets/data/pokedex.js');
const dex = JSON.parse(readFileSync(dexPath, 'utf8').replace(/^window\.POKEDEX = /, '').replace(/;\s*$/, ''));
for (const sp of Object.values(dex)) {
  sp.types = sp.types.filter(t => t !== 'fairy');
  if (!sp.types.length) sp.types = ['normal'];
}
writeFileSync(dexPath, 'window.POKEDEX = ' + JSON.stringify(dex) + ';\n');

const mvPath = path.join(ROOT, 'assets/data/moves.js');
const moves = JSON.parse(readFileSync(mvPath, 'utf8').replace(/^window\.MOVES = /, '').replace(/;\s*$/, ''));
for (const mv of Object.values(moves)) {
  if (mv.type === 'fairy') mv.type = 'normal';
}
writeFileSync(mvPath, 'window.MOVES = ' + JSON.stringify(moves) + ';\n');
console.log('Fairy type removed (Gen 3 accuracy restored).');

