// Browser smoke test: boots the game in headless Chrome/Edge, plays through
// the opening (new game -> walk -> lab -> starter -> rival fight -> wild battle
// -> catch -> menu -> evolution), failing on any console error.
import puppeteer from 'puppeteer-core';
import http from 'node:http';
import { readFileSync, mkdirSync, existsSync } from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '..');
const SHOTS = path.join(ROOT, 'tools/shots');
mkdirSync(SHOTS, { recursive: true });

const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.png': 'image/png' };
const server = http.createServer((req, res) => {
  const p = path.join(ROOT, req.url === '/' ? 'index.html' : decodeURIComponent(req.url.split('?')[0]));
  try {
    res.setHeader('Content-Type', MIME[path.extname(p)] ?? 'application/octet-stream');
    res.end(readFileSync(p));
  } catch { res.statusCode = 404; res.end('nope'); }
});
await new Promise(r => server.listen(0, r));
const PORT = server.address().port;

const exe = ['C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'].find(existsSync);
const browser = await puppeteer.launch({ executablePath: exe, headless: 'new' });
const page = await browser.newPage();
await page.setViewport({ width: 800, height: 600 });

const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));

const sleep = (ms) => new Promise(r => setTimeout(r, ms));
const key = async (k) => { await page.keyboard.press(k); await sleep(140); };
const hold = async (k, ms) => { await page.keyboard.down(k); await sleep(ms); await page.keyboard.up(k); await sleep(80); };
const shot = (name) => page.screenshot({ path: path.join(SHOTS, name + '.png') });
const state = () => page.evaluate(() => ({
  map: Overworld.player.map, x: Overworld.player.x, y: Overworld.player.y,
  party: Game.save.party.map(m => ({ id: m.id, lv: m.level, hp: m.hp })),
  box: Game.save.box.length,
  flags: Game.save.flags, battle: Battle.active(), uiBusy: UI.busy(),
  caught: Object.keys(Game.save.caught).length,
}));
// Press A until UI is idle (dialogs cleared).
async function clearUI(max = 60) {
  for (let i = 0; i < max; i++) {
    const s = await state();
    if (!s.uiBusy && !s.battle) return true;
    await key('KeyZ');
  }
  return false;
}
// Press A until UI idle OR a battle menu is waiting (uiBusy stays, battle active).
async function battleTurnAttack() {
  await key('KeyZ'); // FIGHT
  await sleep(200);
  await key('KeyZ'); // first move
  await sleep(400);
  for (let i = 0; i < 14; i++) {
    await key('KeyZ');
    await sleep(180);
  }
}

await page.goto(`http://localhost:${PORT}/`);
await sleep(1500);
await shot('01-title');

// New game + intro dialogs
await key('KeyZ');
await clearUI();
await shot('02-house');
let s = await state();
console.log('start:', s.map, s.x, s.y, 'uiBusy', s.uiBusy);

// Real movement test: walk down onto the exit mat
await hold('ArrowDown', 700);
await sleep(1400); // door transition
s = await state();
console.log('after walking out:', s.map, s.x, s.y);
if (s.map !== 'pallet') { console.error('FAIL: walking out of house did not warp'); errors.push('walkout failed'); }
await shot('03-pallet');

// Try to leave town without a Pokémon -> should be blocked
await page.evaluate(() => Overworld.setPos('pallet', 9, 1, 'up'));
await hold('ArrowUp', 400);
await sleep(300);
s = await state();
console.log('leave-without-mon block:', s.map, 'uiBusy(msg)', s.uiBusy);
if (s.map !== 'pallet') errors.push('left town without pokemon!');
await clearUI();

// Into the lab, pick Charmander (ball at (4,4); stand at (4,5))
await page.evaluate(() => Overworld.setPos('lab', 4, 5, 'up'));
await key('KeyZ'); await sleep(300);
await shot('04-starter-confirm');
await key('KeyZ'); // YES
// dialog -> rival battle -> fight through it
for (let i = 0; i < 30; i++) {
  s = await state();
  if (s.battle) break;
  await key('KeyZ');
}
await shot('05-rival-battle');
console.log('rival battle started:', (await state()).battle);
for (let i = 0; i < 12; i++) {
  s = await state();
  if (!s.battle) break;
  await battleTurnAttack();
}
await clearUI();
s = await state();
console.log('after rival:', JSON.stringify(s.party), s.flags);
await shot('06-after-rival');

// Walk in pallet for real: north through town to route1
await page.evaluate(() => {
  for (const m of Game.save.party) m.hp = m.stats.hp;
  Overworld.setPos('pallet', 9, 2, 'up');
});
await hold('ArrowUp', 1400);
await sleep(600);
s = await state();
console.log('walked to:', s.map, s.x, s.y);
if (s.map !== 'route1') errors.push('connection pallet->route1 failed');

// Force a wild pidgey and catch it
await page.evaluate(() => { Game.save.bag['poke-ball'] = 10; Overworld.wildBattle(16, 3); });
await sleep(1500);
await shot('07-wild');
await key('ArrowDown'); await key('KeyZ'); // BAG
await sleep(300);
await key('KeyZ'); // poke ball
await sleep(5000); // throw + shakes
for (let i = 0; i < 10; i++) await key('KeyZ');
// finish battle if it broke free
for (let i = 0; i < 10; i++) {
  s = await state();
  if (!s.battle) break;
  await battleTurnAttack();
}
await clearUI();
s = await state();
console.log('after catch attempt: party', JSON.stringify(s.party), 'caught', s.caught);
await shot('08-after-catch');

// Start menu + pokedex
await key('Enter'); await sleep(300);
await shot('09-menu');
await key('KeyZ'); await sleep(400);
await shot('10-pokedex');
await key('Escape'); await sleep(200); await key('Escape'); await sleep(200); await key('Escape');
await clearUI(10);

// Evolution: queue and run (not awaited inside evaluate - it needs key presses)
await page.evaluate(() => {
  const mon = Game.save.party[0];
  mon.level = 16;
  Game.save.pendingEvos.push({ mon, to: POKEDEX[mon.id].evolvesTo[0].to });
  Game.runEvolutions();
});
await sleep(600);
await key('KeyZ'); // "is evolving!" message
await shot('11-evolving');
await sleep(4000); // flicker animation
for (let i = 0; i < 16; i++) await key('KeyZ');
await clearUI();
s = await state();
console.log('after evo: party0 =', JSON.stringify(s.party[0]));
if (s.party[0].id !== 5) errors.push('evolution did not change species: ' + s.party[0].id);
await shot('12-after-evo');

// Save/load roundtrip
await page.evaluate(() => Game.persist());
await page.reload();
await sleep(1200);
await key('KeyZ'); // CONTINUE
await sleep(500);
s = await state();
console.log('after reload+continue:', s.map, JSON.stringify(s.party[0]));
if (!s.party.length) errors.push('save/load roundtrip lost party');
await shot('13-loaded');

console.log(errors.length ? 'CONSOLE ERRORS:\n' + errors.join('\n') : 'NO ERRORS');
await browser.close();
server.close();
process.exit(errors.length ? 1 : 0);

