// Browser smoke test: boots the game in headless Chrome/Edge, plays through
// the opening (new game -> lab -> starter -> rival fight -> route 1 wild battle),
// failing on any console error. Saves screenshots to tools/shots/.
import puppeteer from 'puppeteer-core';
import http from 'node:http';
import { readFileSync, mkdirSync, existsSync } from 'node:fs';
import path from 'node:path';

const ROOT = path.resolve(import.meta.dirname, '..');
const SHOTS = path.join(ROOT, 'tools/shots');
mkdirSync(SHOTS, { recursive: true });

const MIME = { '.html': 'text/html', '.js': 'text/javascript', '.png': 'image/png', '.json': 'application/json' };
const server = http.createServer((req, res) => {
  const p = path.join(ROOT, req.url === '/' ? 'index.html' : decodeURIComponent(req.url.split('?')[0]));
  try {
    res.setHeader('Content-Type', MIME[path.extname(p)] ?? 'application/octet-stream');
    res.end(readFileSync(p));
  } catch { res.statusCode = 404; res.end('nope'); }
});
await new Promise(r => server.listen(0, r));
const PORT = server.address().port;

const exe = ['C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe'].find(existsSync);
const browser = await puppeteer.launch({ executablePath: exe, headless: 'new' });
const page = await browser.newPage();
await page.setViewport({ width: 800, height: 600 });

const errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));

const key = async (k, times = 1, delay = 120) => {
  for (let i = 0; i < times; i++) {
    await page.keyboard.press(k);
    await new Promise(r => setTimeout(r, delay));
  }
};
const mashA = (n, d = 150) => key('KeyZ', n, d);
const shot = (name) => page.screenshot({ path: path.join(SHOTS, name + '.png') });
const state = () => page.evaluate(() => ({
  state: Game.state,
  map: Overworld.player.map, x: Overworld.player.x, y: Overworld.player.y,
  party: Game.save.party.map(m => ({ id: m.id, lv: m.level, hp: m.hp })),
  flags: Game.save.flags,
  battle: Battle.active(),
  uiBusy: UI.busy(),
}));

await page.goto(`http://localhost:${PORT}/`);
await new Promise(r => setTimeout(r, 1500));
await shot('01-title');

// New game
await key('KeyZ'); await new Promise(r => setTimeout(r, 400));
await mashA(8); // intro messages
await shot('02-house');
console.log('after newgame:', JSON.stringify(await state()));

// Walk out of the house: mat is at (4,6), player starts (4,5)
await page.evaluate(() => Overworld.setPos('player-house', 4, 5, 'down'));
await key('ArrowDown', 2, 500);
await new Promise(r => setTimeout(r, 1200));
console.log('after exit:', JSON.stringify(await state()));

// Teleport to lab door and enter, then talk to a ball: starter pick
await page.evaluate(() => Overworld.setPos('lab', 4, 5, 'up'));
await new Promise(r => setTimeout(r, 300));
await key('KeyZ'); // interact with ball (4,4) = charmander
await new Promise(r => setTimeout(r, 400));
await shot('03-starter-confirm');
await key('KeyZ'); // YES
await new Promise(r => setTimeout(r, 400));
await mashA(10, 250); // dialog until rival battle starts
await new Promise(r => setTimeout(r, 800));
await shot('04-rival-battle');
let s = await state();
console.log('rival battle:', JSON.stringify(s));

// Fight: spam attack through the battle (charmander vs squirtle lv5)
for (let round = 0; round < 40; round++) {
  s = await state();
  if (!s.battle) break;
  await mashA(6, 220);
}
await mashA(8, 220); // post-battle dialog
s = await state();
console.log('after rival:', JSON.stringify(s));
await shot('05-after-rival');

// Heal up, go to route 1 grass and force a wild battle
await page.evaluate(() => {
  for (const m of Game.save.party) { m.hp = m.stats.hp; }
  Overworld.setPos('route1', 3, 19, 'up');
  Overworld.wildBattle(16, 3); // pidgey
});
await new Promise(r => setTimeout(r, 1500));
await shot('06-wild-battle');
s = await state();
console.log('wild battle:', JSON.stringify(s));

// Throw a ball at it
await page.evaluate(() => { Game.save.bag['poke-ball'] = 10; });
// menu: FIGHT(0) BAG(1) -> need Down then A
await key('ArrowDown'); await key('KeyZ'); // BAG
await new Promise(r => setTimeout(r, 300));
await shot('07-bag');
await key('KeyZ'); // first item = poke-ball
await new Promise(r => setTimeout(r, 4500)); // throw animation + shakes
await shot('08-throw');
await mashA(10, 250);
s = await state();
console.log('after throw:', JSON.stringify(s));

// If still battling (broke free), finish it with moves
for (let round = 0; round < 40; round++) {
  s = await state();
  if (!s.battle) break;
  await mashA(6, 220);
}
await mashA(6, 200);
s = await state();
console.log('final:', JSON.stringify(s));
await shot('09-overworld-route1');

// Menu test
await key('Enter'); await new Promise(r => setTimeout(r, 300));
await shot('10-menu');
await key('KeyZ'); await new Promise(r => setTimeout(r, 400)); // pokedex
await shot('11-pokedex');
await key('Escape', 3, 200);

// Evolution smoke: force a level-16 charmander level-up via exp
await page.evaluate(async () => {
  const mon = Game.save.party[0];
  Game.save.pendingEvos.push({ mon, to: POKEDEX[mon.id].evolvesTo[0]?.to ?? 17 });
  await Game.runEvolutions();
});
await new Promise(r => setTimeout(r, 1000));
await shot('12-evolving');
await mashA(14, 300);
await new Promise(r => setTimeout(r, 3500));
await mashA(8, 250);
s = await state();
console.log('after evo:', JSON.stringify(s));
await shot('13-after-evo');

console.log(errors.length ? 'CONSOLE ERRORS:\n' + errors.join('\n') : 'NO CONSOLE ERRORS');
await browser.close();
server.close();
process.exit(errors.length ? 1 : 0);

